mapper.select:
SELECT DATE_FORMAT(create_time, '%Y-%m-%d') AS `date`, COALESCE(SUM(pay_amount), 0) AS amount, COUNT(*) AS count FROM `order` WHERE status IN (2, 3)
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d') ORDER BY `date` ASC
